#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_appendf_resize_failure(void) {
    // Setup: create a buffer with some initial content
    buffer_t *buf = helper_create_buffer_with_content("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // Prepare format string and argument
    const char *fmt = " %d";
    int value = 123;

    // Calculate how many allocations occur before the buffer_resize() in buffer_appendf
    // helper_create_buffer_with_content("abc") calls buffer_new_with_copy, which calls buffer_new_with_size
    // That is 2 allocations (struct + data)
    // buffer_appendf will call buffer_resize, which calls realloc (target allocation)
    // So, fail after 2 allocations to hit the realloc in buffer_resize
    malloc_fail_after(2);

    // Test: call buffer_appendf, which should fail due to allocation failure in buffer_resize
    int ret = buffer_appendf(buf, fmt, value);
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer should remain valid and unchanged
    helper_assert_buffer_content(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_appendf_resize_failure);
    return UNITY_END();
}

